import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import { default as primitives } from '@/primitives';
import { default as text } from '@/text';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  // Root container
  const root = new Group();

  // Geometry & material
  const width = 1.0;
  const height = 0.5;
  const geometry = new PlaneGeometry(width, height);
  const baseColor = (config.intent?.visualSpec?.colors?.paper) || '#e8ecf2';
  const material = new MeshBasicNodeMaterial({
    color: baseColor,
    transparent: true,
    depthTest: true,
    depthWrite: true,
  });

  const mesh = new Mesh(geometry, material);
  root.add(mesh);

  // Load texture if provided
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  // Interaction state
  const baseY = root.position.y;
  const timelines = [];

  // Hover handler (rise‑in)
  const onHover = (enter) => {
    const targetY = enter ? baseY + 0.15 : baseY;
    const tl = gsap.timeline({ defaults: { duration: 0.7, ease: 'power3.out' } });
    tl.to(root.position, { y: targetY });
    timelines.push(tl);
  };

  // Click handler (emit and press‑down)
  const onClick = () => {
    // Emit navigation/event
    ctx.emit('hub-pricing.select', {});

    // Press‑down animation
    const tl = gsap.timeline({ defaults: { duration: 0.12, ease: 'back.out(1.7)' } });
    tl.to(root.scale, { x: 0.97, y: 0.97, z: 0.97 }).to(root.scale, { x: 1, y: 1, z: 1 });
    timelines.push(tl);
  };

  // Attach handlers to userData
  root.userData.handlers = {
    hover: onHover,
    click: onClick,
  };

  // Cleanup routine
  root.userData.cleanup = () => {
    // Dispose geometry & material
    geometry.dispose();
    material.dispose();

    // Kill all GSAP timelines
    timelines.forEach((tl) => tl.kill());
    timelines.length = 0;

    // Remove handlers reference
    root.userData.handlers = {};
  };

  // Apply any cinematic primitives listed in config (none in this spec)
  if (Array.isArray(config.cinematicPrimitives)) {
    config.cinematicPrimitives.forEach((prim) => {
      const primitive = ctx.primitives[prim.name];
      if (primitive) {
        const instance = primitive(root, prim.params);
        // Store cleanup for later
        if (instance?.cleanup) {
          const prevCleanup = root.userData.cleanup;
          root.userData.cleanup = () => {
            instance.cleanup();
            if (prevCleanup) prevCleanup();
          };
        }
        // Store timeline if provided
        if (instance?.timeline) {
          timelines.push(instance.timeline);
        }
      }
    });
  }

  return root;
}
